'use client'

import { useRef, useMemo } from 'react'
import * as THREE from 'three'

// Simple noise function for terrain generation
function noise3D(x: number, y: number, z: number): number {
  const n = Math.sin(x * 12.9898 + y * 78.233 + z * 45.164) * 43758.5453
  return n - Math.floor(n)
}

function fbm(x: number, y: number, z: number, octaves: number): number {
  let value = 0
  let amplitude = 1
  let frequency = 1
  let totalAmplitude = 0

  for (let i = 0; i < octaves; i++) {
    value += amplitude * (noise3D(x * frequency, y * frequency, z * frequency) * 2 - 1)
    totalAmplitude += amplitude
    amplitude *= 0.5
    frequency *= 2
  }

  return value / totalAmplitude
}

export function Planet() {
  const meshRef = useRef<THREE.Mesh>(null)

  const geometry = useMemo(() => {
    const geo = new THREE.IcosahedronGeometry(1.5, 5)
    const positions = geo.attributes.position
    const colors = new Float32Array(positions.count * 3)

    // Deform vertices and assign colors based on terrain
    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i)
      const y = positions.getY(i)
      const z = positions.getZ(i)

      // Normalize to unit sphere
      const len = Math.sqrt(x * x + y * y + z * z)
      const nx = x / len
      const ny = y / len
      const nz = z / len

      // Generate terrain height
      const continentNoise = fbm(nx * 1.5, ny * 1.5, nz * 1.5, 4)
      const detailNoise = fbm(nx * 4, ny * 4, nz * 4, 3) * 0.3

      const isLand = continentNoise > -0.1
      const height = isLand
        ? 1.5 + Math.max(0, continentNoise + detailNoise) * 0.12
        : 1.5 - Math.abs(continentNoise) * 0.02

      // Set vertex position with height
      positions.setXYZ(i, nx * height, ny * height, nz * height)

      // Color based on terrain type
      if (!isLand) {
        // Ocean - deep blue to light blue
        const depth = Math.abs(continentNoise)
        colors[i * 3] = 0.1 + depth * 0.1
        colors[i * 3 + 1] = 0.4 + depth * 0.2
        colors[i * 3 + 2] = 0.7 + depth * 0.1
      } else if (continentNoise < 0.05) {
        // Beach/sand
        colors[i * 3] = 0.85
        colors[i * 3 + 1] = 0.78
        colors[i * 3 + 2] = 0.55
      } else if (continentNoise > 0.4) {
        // Mountain/rock
        colors[i * 3] = 0.5
        colors[i * 3 + 1] = 0.48
        colors[i * 3 + 2] = 0.45
      } else {
        // Grass - varied greens
        const grassVar = noise3D(nx * 8, ny * 8, nz * 8)
        colors[i * 3] = 0.25 + grassVar * 0.15
        colors[i * 3 + 1] = 0.6 + grassVar * 0.2
        colors[i * 3 + 2] = 0.2 + grassVar * 0.1
      }
    }

    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    geo.computeVertexNormals()
    return geo
  }, [])

  return (
    <mesh ref={meshRef} geometry={geometry}>
      <meshLambertMaterial vertexColors flatShading />
    </mesh>
  )
}
